const keywords = automaRefData('variables', 'keywords') || [];
const index = Number(automaRefData('variables', 'keywordIndex') || 0);
if (index >= keywords.length) {
  automaSetVariable('currentKeyword', '');
  automaSetVariable('hasNextPage', false);
  automaNextBlock('done');
} else {
  automaSetVariable('currentKeyword', keywords[index]);
  automaSetVariable('hasNextPage', true);
  automaNextBlock('open-search');
}

const next = document.querySelector('a#pnnext, a[aria-label="下一页"], a[aria-label="Next page"], a[aria-label="Next"]');
automaSetVariable('hasNextPage', Boolean(next));
if (next) {
  automaNextBlock('click-next');
} else {
  automaNextBlock('next-keyword');
}

const index = Number(automaRefData('variables', 'keywordIndex') || 0);
automaSetVariable('keywordIndex', index + 1);
automaNextBlock('init-keyword');
